with open('/root/DATA/products/CoachForce.json') as f:
    data = json.load(f)

# Check meeting transcripts for market research report references
for i, mt in enumerate(data['meeting_transcripts']):
    text = json.dumps(mt).lower()
    if 'market research' in text:
        print(f'=== Meeting Transcript {i} ===')
        if isinstance(mt, dict):
            for k in mt:
                if k != 'transcript':
                    print(f'  {k}: {mt[k]}')
            if 'transcript' in mt:
                print(f'  transcript (first 500 chars): {str(mt[\"transcript\"])[:500]}')
        else:
            print(str(mt)[:500])
        print()
"

