for i, mt in enumerate(data['meeting_transcripts']):
    text = json.dumps(mt).lower()
    if 'competitor' in text or 'strength' in text or 'weakness' in text or 'tailorai' in text or 'smartsuggest' in text or 'personaai' in text:
        print(f'=== Meeting Transcript {i} ===')
        if isinstance(mt, dict):
            for k in mt:
                if k != 'transcript':
                    print(f'  {k}: {mt[k]}')
            if 'transcript' in mt:
                print(f'  transcript (first 1000 chars): {str(mt[\"transcript\"])[:1000]}')
        print()

# Check meeting chats too
print('=== Meeting Chats ===')
print(f'Number of meeting chats: {len(data[\"meeting_chats\"])}')
for i, mc in enumerate(data['meeting_chats']):
    text = json.dumps(mc).lower()
    if 'competitor' in text or 'strength' in text or 'weakness' in text:
        print(f'Meeting chat {i}: {json.dumps(mc, indent=2)[:500]}')
